// Glosario del curso. La web marca sola estos términos en las lecciones y rituales
// (la primera vez que aparecen en cada sección) y abre una ventana con su explicación.
//
// Cada entrada:
//   id: identificador único (sin espacios).
//   t:  término tal como se muestra en la ventana y en la página Glosario.
//   d:  explicación breve, para quien empieza (una a tres frases).
//   f:  formas que se buscan en el texto (plurales, variantes). Si falta, se busca t.
//   cs: true si las formas deben coincidir con mayúsculas exactas (para no marcar palabras comunes).
//   l:  lección donde aparece por primera vez (o se estudia), si la hay.
//   una: true para términos muy frecuentes (y personas): se marcan una sola vez por página.
//
// Para lecciones nuevas basta con añadir aquí los términos. En el HTML de una lección:
//   <span data-glosa="id">texto</span> marca a mano un texto con la entrada id;
//   class="no-glosa" en un elemento evita que se marque nada dentro de él.
window.GLOSARIO = [
  // ── Tradiciones y conceptos generales ──
  { id: "cabala", una: true, t: "Cábala", l: 1, f: ["Cábala", "Cábalas", "Cabalá"],
    d: "Tradición mística nacida dentro del judaísmo, en el sur de Francia y España en los siglos XII y XIII, que busca comprender a Dios, el universo y el alma. La palabra hebrea Qabalah significa «lo recibido»: una sabiduría que se transmite de maestro a discípulo." },
  { id: "cabalista", una: true, t: "Cabalista", l: 1, f: ["cabalista", "cabalistas", "cabalístico", "cabalística", "cabalísticos", "cabalísticas"],
    d: "Persona que estudia y practica la Cábala. También se usa como adjetivo: un símbolo cabalístico es uno que procede de la Cábala." },
  { id: "kabbalah-judia", una: true, t: "Kabbalah judía", l: 1, f: ["Kabbalah judía", "Cábala judía", "mística judía"],
    d: "La Cábala original: una mística religiosa judía, viva todavía hoy, centrada en la Torá y en cumplir la ley judía. Su libro más famoso es el Zohar. No usa tarot ni astrología." },
  { id: "cabala-cristiana", una: true, t: "Cabala cristiana", l: 1, f: ["Cabala cristiana", "Cábala cristiana", "cabalistas cristianos"],
    d: "Corriente del Renacimiento (siglos XV a XVII) en la que sabios cristianos aprendieron hebreo y leyeron a los cabalistas judíos para buscar en sus textos pruebas de las verdades cristianas." },
  { id: "qabalah-hermetica", una: true, t: "Qabalah hermética", l: 1, f: ["Qabalah hermética"],
    d: "La Cábala de las sociedades esotéricas del siglo XIX, sobre todo la Golden Dawn. Usa el Árbol de la Vida como mapa de correspondencias: letras hebreas, cartas del tarot, planetas, colores. Es la que prioriza este curso." },
  { id: "hermetismo", una: true, t: "Hermetismo", l: 1, f: ["hermetismo", "hermético", "hermética", "herméticos", "herméticas", "hermetista", "hermetistas"],
    d: "Filosofía y conjunto de enseñanzas atribuidas al legendario sabio Hermes Trismegisto. Su idea central es que todo está conectado: «como es arriba, es abajo»." },
  { id: "hermes", una: true, t: "Hermes Trismegisto", l: 1, f: ["Hermes Trismegisto"],
    d: "«Hermes, el tres veces grande». Figura legendaria nacida de fundir al dios griego Hermes con el dios egipcio Thot. Se le atribuyeron textos escritos en realidad en el Egipto romano (siglos II y III)." },
  { id: "thot", t: "Thot", l: 1, cs: true, f: ["Thot"],
    d: "Dios egipcio de la sabiduría, la escritura y la magia, representado con cabeza de ibis. Los griegos lo identificaron con su dios Hermes." },
  { id: "corpus", t: "Corpus Hermeticum", l: 1,
    d: "«Conjunto de escritos de Hermes». Textos griegos de los siglos II y III atribuidos a Hermes Trismegisto. Marsilio Ficino los tradujo al latín en 1463 creyéndolos más antiguos que Moisés." },
  { id: "tabla-esmeralda", t: "Tabla Esmeralda", l: 2,
    d: "Texto muy breve atribuido a Hermes, de donde sale la frase «como es arriba, es abajo». Se conoce primero por fuentes árabes medievales y se tradujo al latín en el siglo XII. Se estudia en la lección 11." },
  { id: "kybalion", una: true, t: "El Kybalión", l: 1, f: ["Kybalión"],
    d: "Libro publicado en 1908 en Estados Unidos, firmado por «Tres Iniciados» (probablemente William Walker Atkinson). Resume el hermetismo en siete principios. No es un texto egipcio antiguo." },
  { id: "esoterico", una: true, t: "Esotérico", l: 1, f: ["esotérico", "esotérica", "esotéricos", "esotéricas", "esoterismo"],
    d: "Del griego «de dentro»: un saber reservado a quienes han sido iniciados en él, frente al saber público. Se usa para las sociedades y doctrinas ocultistas." },
  { id: "mistica", una: true, t: "Mística", l: 1, f: ["mística", "místico", "místicos", "místicas"],
    d: "Búsqueda de una experiencia directa de lo divino, más allá de los ritos y las creencias. Hay mística judía, cristiana, islámica y de muchas otras tradiciones." },
  { id: "iniciacion", una: true, t: "Iniciación", l: 1, f: ["iniciación", "iniciaciones", "iniciado", "iniciados", "Iniciados"],
    d: "Ceremonia por la que alguien entra en un grupo o en un nivel de conocimiento, y que marca un antes y un después. El iniciado es quien la ha recibido." },
  { id: "correspondencias", una: true, t: "Correspondencias", l: 1, f: ["correspondencias", "correspondencia"],
    d: "Equivalencias entre cosas de distintos planos: una letra, un planeta, un color y una carta del tarot que se consideran la misma idea expresada de formas diferentes. Son la base de la Qabalah hermética." },
  { id: "judaismo", una: true, t: "Judaísmo", l: 1, f: ["judaísmo"],
    d: "La religión del pueblo judío, basada en la Torá y en la tradición de los rabinos. Es la religión en la que nació la Cábala." },
  { id: "converso", t: "Judío converso", l: 1, f: ["judío converso", "judíos conversos", "judeoconverso", "judeoconversos", "converso", "conversos"],
    d: "Judío que se convirtió al cristianismo, muchas veces bajo presión (en España, sobre todo tras los ataques de 1391 y la expulsión de 1492). Varios conversos enseñaron hebreo y Cábala a los cabalistas cristianos del Renacimiento." },
  { id: "sefardi", t: "Sefardí", l: 1, f: ["sefardí", "sefardíes", "Sefardí", "sefardita", "sefarditas"],
    d: "Judío de la península ibérica (Sefarad, en hebreo) o descendiente de los expulsados en 1492. Las comunidades sefardíes conservan todavía oraciones y costumbres de la Castilla medieval." },
  { id: "call", t: "Call", l: 1, cs: true, f: ["el Call"],
    d: "Nombre del barrio judío en las ciudades de Cataluña y Baleares, como el de Girona." },
  { id: "sinagoga", t: "Sinagoga", l: 1, f: ["sinagoga", "sinagogas"],
    d: "Lugar de reunión, oración y estudio de una comunidad judía." },
  { id: "renacimiento", una: true, t: "Renacimiento", l: 1, cs: true, f: ["Renacimiento", "renacentista", "renacentistas"],
    d: "Época de la historia europea (siglos XV y XVI, con Italia como centro) en la que se recuperaron los textos y el arte de la Antigüedad griega y romana." },
  { id: "humanista", t: "Humanista", l: 1, f: ["humanista", "humanistas"],
    d: "Sabio del Renacimiento dedicado a estudiar las lenguas y los textos antiguos (latín, griego y a veces hebreo)." },
  { id: "raiz", t: "Raíz hebrea", l: 1, f: ["raíz hebrea"],
    d: "En hebreo casi todas las palabras se forman a partir de una raíz de tres consonantes que lleva el significado básico. De q-b-l, «recibir», sale Qabalah." },

  // ── Libros y textos ──
  { id: "tora", una: true, t: "Torá", l: 1, f: ["Torá", "TORA", "Tora"],
    d: "En hebreo, «enseñanza» o «ley». Son los cinco primeros libros de la Biblia (Génesis, Éxodo, Levítico, Números y Deuteronomio), que la tradición atribuye a Moisés. En sinagoga se leen de un rollo escrito a mano. En sentido amplio, toda la enseñanza judía." },
  { id: "biblia-hebrea", t: "Biblia hebrea", l: 1, f: ["Biblia hebrea", "Antiguo Testamento"],
    d: "Los libros sagrados del judaísmo (en hebreo, Tanaj): la Torá, los Profetas y los Escritos. Los cristianos los llaman Antiguo Testamento." },
  { id: "zohar", una: true, t: "Zohar", l: 1, f: ["Zohar", "Zóhar"],
    d: "«Esplendor». El libro más importante de la Cábala judía, escrito en arameo en Castilla hacia 1280. Se presenta como obra de un rabino del siglo II, pero los historiadores lo atribuyen sobre todo a Moisés de León." },
  { id: "sefer-yetsira", una: true, t: "Séfer Yetsirá", l: 3, f: ["Séfer Yetsirá", "Sefer Yetsirá"],
    d: "«Libro de la Formación». Librito hebreo muy antiguo (entre los siglos II y VI) que explica cómo se creó el mundo con los diez números y las 22 letras. Se estudia en la lección 4." },
  { id: "bahir", t: "Bahir", l: 3, cs: true, f: ["Bahir"],
    d: "«Claro, luminoso». Uno de los primeros libros de Cábala, aparecido en Provenza hacia 1180. Ya trata las sefirot como poderes de Dios y habla de un árbol cósmico." },
  { id: "tikunei", t: "Tikunéi Zóhar", l: 3, f: ["Tikunéi Zóhar"],
    d: "«Correcciones del Zohar». Obra escrita poco después del Zohar (hacia 1300), que lo comenta. Empieza con la oración Pataj Eliyahu." },
  { id: "enoc", t: "El libro de Enoc", l: 2, f: ["libro de Enoc", "1 Enoc"],
    d: "Texto judío escrito entre los siglos III y I a. C. y atribuido al patriarca Enoc, que sube a los cielos en visiones. No entró en la Biblia judía ni en la de casi todas las Iglesias cristianas, pero influyó mucho en la mística." },
  { id: "palacios", t: "Palacios celestiales", l: 2, f: ["palacios celestiales"],
    d: "Mística judía antigua (en hebreo, Hejalot, «palacios») en la que el místico asciende en visión por siete palacios hasta el trono de Dios. Se verá en la lección 10." },
  { id: "padrenuestro", t: "Padrenuestro", l: 2, f: ["Padrenuestro"],
    d: "La oración que, según los Evangelios, enseñó Jesús. Algunas versiones terminan con «porque tuyo es el reino, el poder y la gloria», la frase de la Cruz Cabalística." },

  // ── Tarot ──
  { id: "tarot", una: true, t: "Tarot", l: 1, cs: true, f: ["tarot", "Tarot"],
    d: "Baraja de 78 cartas: 22 arcanos mayores, con figuras como El Mago o La Luna, y 56 arcanos menores en cuatro palos. Nació en Italia en el siglo XV como juego de cartas; su uso esotérico empieza en el siglo XVIII." },
  { id: "arcanos", una: true, t: "Arcanos mayores y menores", l: 1, f: ["arcanos mayores", "arcano mayor", "arcanos menores", "arcano menor", "Arcanos Mayores", "arcanos", "arcano"],
    d: "«Arcano» significa «secreto». Los 22 arcanos mayores son las cartas con figuras y número romano; los 56 menores, las cartas de los cuatro palos (bastos, copas, espadas y oros)." },
  { id: "rider-waite", una: true, t: "Rider-Waite", l: 1,
    d: "La baraja de tarot que usa el curso, publicada en 1909 por Arthur E. Waite y dibujada por Pamela Colman Smith, ambos de la Golden Dawn. Su nombre viene de la editorial Rider." },
  { id: "marsella", t: "Tarot de Marsella", l: 1,
    d: "La baraja tradicional francesa de los siglos XVII y XVIII, que usaba Éliphas Lévi. Su orden y sus dibujos difieren en algunos puntos del Rider-Waite." },
  { id: "thoth", t: "Tarot Thoth", l: 1, f: ["tarot Thoth"],
    d: "Baraja diseñada por Aleister Crowley y pintada por Lady Frieda Harris (1938-1943), con símbolos de la Golden Dawn y del sistema propio de Crowley." },

  // ── Personas ──
  { id: "levi", una: true, t: "Éliphas Lévi", l: 1, f: ["Éliphas Lévi", "Lévi"],
    d: "Seudónimo del francés Alphonse-Louis Constant (1810-1875). En Dogma y ritual de la alta magia unió por sistema las 22 letras hebreas y los 22 arcanos mayores. Es el padre del ocultismo moderno." },
  { id: "crowley", una: true, t: "Aleister Crowley", l: 1, f: ["Aleister Crowley", "Crowley"],
    d: "Ocultista inglés (1875-1947), miembro de la Golden Dawn, que luego fundó su propio sistema, Thelema. Publicó las tablas de correspondencias de la orden en Liber 777 y diseñó el tarot Thoth." },
  { id: "waite", una: true, t: "Arthur E. Waite", l: 1, f: ["Arthur E. Waite"],
    d: "Escritor inglés (1857-1942), masón y miembro de la Golden Dawn, autor de la baraja Rider-Waite junto a la ilustradora Pamela Colman Smith." },
  { id: "regardie", una: true, t: "Israel Regardie", l: 2, f: ["Israel Regardie", "Regardie"],
    d: "Ocultista (1907-1985), secretario de Crowley y miembro de una rama de la Golden Dawn. Publicó entre 1937 y 1940 los rituales completos de la orden." },
  { id: "fortune", una: true, t: "Dion Fortune", l: 2,
    d: "Seudónimo de la inglesa Violet Firth (1890-1946), miembro de la Golden Dawn y fundadora de su propia escuela. Su libro La Cábala mística (1935) es un manual clásico de la Qabalah hermética." },
  { id: "hall", una: true, t: "Manly P. Hall", l: 1, cs: true, f: ["Manly P. Hall", "Hall"],
    d: "Escritor estadounidense de origen canadiense (1901-1990). Su gran obra, Las enseñanzas secretas de todas las épocas (1928), resume las tradiciones esotéricas; el curso la cita a menudo, señalando dónde mezcla historia y leyenda." },
  { id: "papus", una: true, t: "Papus", l: 3, cs: true, f: ["Papus"],
    d: "Seudónimo del médico francés Gérard Encausse (1865-1916), ocultista y autor de El tarot de los bohemios (1889), que sigue el sistema de Lévi." },
  { id: "pico", una: true, t: "Pico della Mirandola", l: 1,
    d: "Humanista italiano (1463-1494), considerado el primer cabalista cristiano. Defendía que la Cábala confirmaba la verdad del cristianismo." },
  { id: "reuchlin", una: true, t: "Johannes Reuchlin", l: 1, f: ["Johannes Reuchlin", "Reuchlin"],
    d: "Humanista alemán (1455-1522), gran estudioso del hebreo y autor de Sobre el arte cabalístico (1517), obra central de la Cabala cristiana." },
  { id: "ficino", una: true, t: "Marsilio Ficino", l: 1,
    d: "Filósofo florentino (1433-1499) que tradujo al latín a Platón y el Corpus Hermeticum, y difundió el hermetismo en el Renacimiento." },
  { id: "pike", una: true, t: "Albert Pike", l: 1, f: ["Albert Pike"],
    d: "Abogado y militar estadounidense (1809-1891), jefe del Rito Escocés en el sur de Estados Unidos y autor de Moral y Dogma (1871). Las acusaciones de satanismo contra él fueron un fraude de Léo Taxil." },
  { id: "luria", una: true, t: "Isaac Luria", l: 3,
    d: "Cabalista judío (1534-1572) de Safed, en Galilea. Su escuela creó el gran relato del tsimtsum, la rotura de los vasos y el tikún, que cambió la Cábala posterior." },
  { id: "plotino", una: true, t: "Plotino", l: 2, cs: true, f: ["Plotino"],
    d: "Filósofo griego nacido en Egipto (205-270), fundador del neoplatonismo. Explicó el mundo como una emanación que fluye del Uno, idea que heredaron el hermetismo y la Cábala." },
  { id: "pitagoras", una: true, t: "Pitágoras y los pitagóricos", l: 3, f: ["Pitágoras", "pitagóricos", "pitagórica", "pitagórico", "pitagóricas"],
    d: "Pitágoras (siglo VI a. C.) fundó una escuela filosófica y religiosa en el sur de Italia. Sus seguidores veían en los números los principios de todo lo que existe." },
  { id: "fludd", una: true, t: "Robert Fludd", l: 2,
    d: "Médico y hermetista inglés (1574-1637), defensor de los rosacruces, famoso por sus grabados sobre el macrocosmos y el microcosmos." },
  { id: "agrippa", una: true, t: "Cornelio Agrippa", l: 3, f: ["Cornelio Agrippa", "Agrippa"],
    d: "Médico y filósofo alemán (1486-1535), autor de De occulta philosophia (1533), la gran enciclopedia de la magia del Renacimiento, que une hermetismo, astrología y Cabala cristiana." },

  // ── Masonería y sociedades ──
  { id: "masoneria", una: true, t: "Masonería", l: 1, f: ["masonería", "masón", "masones", "masónico", "masónica", "masónicos", "masónicas", "francmasonería"],
    d: "Fraternidad nacida de los gremios de canteros medievales, que desde hacia 1600 admitió a no constructores y se volvió filosófica. Usa los símbolos de la construcción para hablar del perfeccionamiento personal." },
  { id: "fraternidad", t: "Fraternidad", l: 1, f: ["fraternidad", "fraternidades", "hermandad", "hermandades"],
    d: "Asociación cuyos miembros se tratan como hermanos y comparten unos fines, unas normas y a veces unos ritos. La masonería y los rosacruces se presentan así." },
  { id: "logia", t: "Logia", l: 1, f: ["logia", "logias", "Gran Logia"],
    d: "El grupo local de masones y también el lugar donde se reúnen. Una Gran Logia agrupa a varias logias bajo unas mismas reglas; la primera se fundó en Londres en 1717." },
  { id: "grado", t: "Grado", l: 1, f: ["grados"],
    d: "Cada nivel de iniciación de una sociedad como la masonería o la Golden Dawn. Se recibe con una ceremonia y da acceso a nuevos símbolos y enseñanzas." },
  { id: "rito", t: "Rito", l: 1, f: ["Rito Escocés Antiguo y Aceptado", "Rito Escocés", "rito"],
    d: "En masonería, un sistema de grados con sus ceremonias. El Rito Escocés Antiguo y Aceptado tiene 33 grados y nació en Charleston (Estados Unidos) en 1801, no en Escocia." },
  { id: "tablero", t: "Tablero de trazado", l: 1, f: ["tablero de trazado", "tableros de trazado"],
    d: "Lámina con los símbolos de un grado masónico, que se muestra al nuevo masón para explicárselos." },
  { id: "jacob", t: "Escalera de Jacob", l: 1,
    d: "La escalera que el patriarca Jacob ve en sueños, por la que suben y bajan ángeles entre la tierra y el cielo (Génesis 28:12). En masonería simboliza el camino de perfeccionamiento." },
  { id: "piedra", t: "Piedra bruta y piedra pulida", l: 1, f: ["piedra bruta", "piedra pulida"],
    d: "Símbolos masónicos: la piedra sin tallar es la persona antes de trabajarse a sí misma; la piedra pulida, la persona ya formada." },
  { id: "boaz", t: "Boaz y Jaquín", l: 1, cs: true, f: ["Boaz", "Jaquín"],
    d: "Las dos columnas de bronce que, según la Biblia, estaban a la entrada del Templo de Salomón (1 Reyes 7:21). Boaz es la negra y Jaquín la blanca. Aparecen en las logias masónicas y en La Sacerdotisa del Rider-Waite." },
  { id: "templo", t: "Templo de Salomón", l: 1, f: ["Templo de Salomón", "Templo del rey Salomón", "templo de Salomón"],
    d: "El primer templo de Jerusalén, que según la Biblia construyó el rey Salomón hacia el siglo X a. C. y destruyeron los babilonios en el 587 a. C. Es el gran modelo simbólico de la masonería." },
  { id: "golden-dawn", una: true, t: "Golden Dawn", l: 1, f: ["Golden Dawn", "Aurora Dorada"],
    d: "La Orden Hermética de la Aurora Dorada, sociedad esotérica fundada en Londres en 1888 por tres masones. Unió Cábala, tarot, astrología y magia ceremonial en un solo sistema, el que sigue la baraja Rider-Waite." },
  { id: "rosacruces", t: "Rosacruces", l: 1, f: ["rosacruces", "rosacruz", "Rosacruz"],
    d: "Movimiento místico cristiano surgido en Alemania con unos manifiestos publicados entre 1614 y 1616, que anunciaban una hermandad secreta fundada por el legendario Christian Rosenkreuz. Esa hermandad seguramente nunca existió, pero inspiró muchas sociedades posteriores. Se estudian en la lección 11." },
  { id: "sria", t: "SRIA", l: 1, cs: true, f: ["SRIA"],
    d: "Societas Rosicruciana in Anglia, sociedad rosacruz inglesa fundada en 1867 que solo admitía a masones. De ella salieron los fundadores de la Golden Dawn." },
  { id: "magia-ceremonial", t: "Magia ceremonial", l: 3, f: ["magia ceremonial"],
    d: "Práctica que usa rituales elaborados (gestos, palabras, símbolos, objetos) para actuar sobre la propia conciencia y, según sus practicantes, sobre el mundo. La Golden Dawn fue su gran escuela moderna." },
  { id: "nueva-era", t: "Nueva Era", l: 3, cs: true, f: ["Nueva Era"],
    d: "Movimiento espiritual difuso que se extendió desde los años setenta, mezclando ideas orientales, esoterismo y psicología. Muchas afirmaciones que circulan hoy sobre geometría sagrada vienen de él." },
  { id: "nuevo-pensamiento", t: "Nuevo Pensamiento", l: 3, f: ["Nuevo Pensamiento", "ley de la atracción"],
    d: "Movimiento estadounidense del siglo XIX según el cual el pensamiento moldea la realidad. De él viene la «ley de la atracción», la idea de que basta con pensar algo para atraerlo." },
  { id: "consagracion", una: true, t: "Consagración", l: 1, f: ["consagración", "consagrar", "consagrada", "consagrado"],
    d: "Ritual que dedica un objeto, como la baraja, a un uso sagrado y lo separa del uso cotidiano. El curso lo explica en la página de Rituales." },

  // ── Lección 2 ──
  { id: "ain", t: "Ain", l: 2, cs: true, f: ["Ain"],
    d: "«Nada». En la Qabalah hermética, el primero de los tres velos: lo que está más allá de todo concepto, antes de que exista algo." },
  { id: "ain-soph", t: "Ain Soph", l: 2, f: ["Ain Soph", "Ein Sof"],
    d: "«Sin fin», lo infinito. En la Cábala judía (Ein Sof) es el nombre de Dios tal como es en sí mismo, antes de manifestarse. En la hermética es el segundo velo." },
  { id: "ain-soph-aur", t: "Ain Soph Aur", l: 2,
    d: "«Luz infinita». El tercer velo: el infinito convertido en luz, a punto de concentrarse en el primer punto, Kéter." },
  { id: "velos", t: "Los tres velos de la existencia negativa", l: 2, f: ["velos de la existencia negativa", "tres velos"],
    d: "Ain, Ain Soph y Ain Soph Aur: las tres capas de lo que hay antes de todo. «Negativa» no significa mala, sino que aún no es nada concreto." },
  { id: "arij-anpin", t: "Arij Anpín", l: 2, f: ["Arij Anpín", "Arikh Anpin"],
    d: "«El Rostro Largo» o «el Paciente», en arameo. En el Zóhar, el aspecto más alto de Dios, ligado a Kéter, al que identifica con el Anciano de los Días del libro de Daniel." },
  { id: "trece-atributos", t: "Trece atributos de misericordia", l: 2, f: ["trece atributos de misericordia", "trece atributos"],
    d: "Las trece cualidades de Dios que la tradición judía lee en Éxodo 34:6-7 («compasivo y clemente, lento a la ira…»). El Zóhar las relaciona con las trece partes de la barba de Arij Anpín." },
  { id: "emanacion", t: "Emanación", l: 2, f: ["emanación", "emanar", "emana"],
    d: "La idea de que el mundo no se fabrica desde fuera, como un carpintero hace una mesa, sino que fluye de su origen como la luz del sol, sin que el origen pierda nada." },
  { id: "rayo", t: "El Rayo", l: 2, cs: true, f: ["el Rayo", "Rayo"],
    d: "El camino en zigzag que sigue la luz al bajar por las diez sefirot, de Kéter a Maljut. También se le llama la Espada Flamígera." },
  { id: "macrocosmos", t: "Macrocosmos", l: 2,
    d: "«El gran mundo»: el universo entero, visto como un todo ordenado que se refleja en el ser humano." },
  { id: "microcosmos", t: "Microcosmos", l: 2, f: ["microcosmos", "microcosmo"],
    d: "«El pequeño mundo»: el ser humano, hecho con el mismo plan que el universo. Por eso el Árbol de la Vida se puede colocar sobre el cuerpo." },
  { id: "planos", t: "Planos de existencia", l: 2, f: ["planos de existencia", "subplanos"],
    d: "Niveles de la realidad, de lo más sutil a lo más denso. El Kybalión habla de tres (físico, mental y espiritual); la Cábala, de cuatro mundos." },
  { id: "cuatro-mundos", t: "Los cuatro mundos", l: 2, f: ["cuatro mundos"],
    d: "Los cuatro niveles por los que baja la luz según la Cábala: Atsilut (emanación), Beriá (creación), Yetsirá (formación) y Asiá (acción). Se estudian en la lección 3." },
  { id: "nefesh", t: "Nefesh", l: 2, cs: true, f: ["Nefesh"],
    d: "«Aliento, ser vivo». La parte vital del alma: el cuerpo, los instintos y las necesidades básicas." },
  { id: "ruach", t: "Ruach", l: 2, cs: true, f: ["Ruach"],
    d: "«Viento, espíritu». El yo consciente: la mente, las emociones y la voluntad. Se sitúa en el centro del Árbol, a la altura del corazón." },
  { id: "neshamah", t: "Neshamah", l: 2, cs: true, f: ["Neshamah"],
    d: "«Soplo, respiración». El alma superior: la intuición espiritual y la conexión con lo divino." },
  { id: "jaya", t: "Jayá y Yejidá", l: 2, cs: true, f: ["Jayá", "Yejidá"],
    d: "«La viva» y «la única». Los dos niveles más altos del alma que añadió la Cábala posterior al Zohar, por encima de la Neshamah." },
  { id: "letras-finales", t: "Letras finales", l: 2, f: ["letras finales", "formas finales", "forma final"],
    d: "Cinco letras hebreas (Kaf, Mem, Nun, Pe y Tsadi) cambian de forma cuando van al final de una palabra. Su valor numérico básico es el mismo." },
  { id: "daat", t: "Daat", l: 2, cs: true, f: ["Daat", "daat"],
    d: "«Conocimiento». En la Qabalah hermética, un lugar oculto y sin número en el Árbol, sobre el Abismo, entre las tres sefirot de arriba y las siete de abajo. No es una sefirá más." },
  { id: "cruz-cabalistica", una: true, t: "Cruz Cabalística", l: 2,
    d: "El gesto básico de la Golden Dawn: se traza sobre el cuerpo una cruz de luz mientras se dicen en hebreo las palabras «tuyo es el reino, el poder y la gloria, por siempre, amén». Abre y cierra toda práctica." },

  // ── Lección 3: el Árbol ──
  { id: "arbol", una: true, t: "Árbol de la Vida", l: 1, f: ["Árbol de la Vida", "Árbol de las sefirot", "Ets Jayim"],
    d: "Diagrama de diez círculos (las sefirot) unidos por 22 senderos, que la Cábala usa como mapa del universo y del ser humano. En hebreo, Ets Jayim. Se estudia a fondo en la lección 3." },
  { id: "sefirot", una: true, t: "Sefirot (sefirá)", l: 1, f: ["sefirot", "sefirá", "Sefirot", "Sefirá"],
    d: "Los diez círculos del Árbol de la Vida: los diez modos en que lo infinito se manifiesta, de Kéter (la Corona) a Maljut (el Reino). En singular, sefirá. La palabra se relaciona con «contar» y con «zafiro»." },
  { id: "senderos", t: "Senderos", l: 3, f: ["senderos", "sendero"],
    d: "Las 22 líneas que unen las sefirot del Árbol. Cada una corresponde a una letra hebrea y a un arcano mayor del tarot (lección 5)." },
  { id: "keter", t: "Kéter", l: 3, cs: true, f: ["Kéter"],
    d: "«La Corona». Primera sefirá: la voluntad pura, el origen, el primer punto de la luz. Está en lo alto de la columna central." },
  { id: "jojma", t: "Jojmá", l: 3, f: ["Jojmá", "jojmá"],
    d: "«La Sabiduría». Segunda sefirá: el impulso creador, el Padre. Encabeza la columna de la Misericordia." },
  { id: "bina", t: "Biná", l: 3, cs: true, f: ["Biná"],
    d: "«El Entendimiento». Tercera sefirá: la forma, el molde, la Madre. Encabeza la columna de la Severidad." },
  { id: "jesed", t: "Jésed", l: 3, cs: true, f: ["Jésed"],
    d: "«La Misericordia». Cuarta sefirá: la generosidad que se expande. También se llama Guedulá, «grandeza»." },
  { id: "guevura", t: "Guevurá", l: 2, cs: true, f: ["Guevurá", "ve-Guevurá"],
    d: "«La Fuerza, el Rigor». Quinta sefirá: el límite, la disciplina y el juicio, que equilibra a Jésed. En la Cruz Cabalística se toca el hombro derecho." },
  { id: "guedula", t: "Guedulá", l: 2, cs: true, f: ["Guedulá", "ve-Guedulá"],
    d: "«Grandeza, gloria». Otro nombre de Jésed, la cuarta sefirá. En la Cruz Cabalística se toca el hombro izquierdo." },
  { id: "tiferet", t: "Tiféret", l: 3, cs: true, f: ["Tiféret"],
    d: "«La Belleza». Sexta sefirá, en el centro del Árbol: el equilibrio y el corazón, asociada al Sol." },
  { id: "netsaj", t: "Nétsaj", l: 3, cs: true, f: ["Nétsaj"],
    d: "«La Victoria». Séptima sefirá: los sentimientos, el deseo y el arte, asociada a Venus." },
  { id: "hod", t: "Hod", l: 3, cs: true, f: ["Hod"],
    d: "«El Esplendor». Octava sefirá: el intelecto, el lenguaje y los símbolos, asociada a Mercurio." },
  { id: "yesod", t: "Yesod", l: 3, cs: true, f: ["Yesod"],
    d: "«El Fundamento». Novena sefirá: la imaginación y los sueños, asociada a la Luna." },
  { id: "maljut", t: "Maljut", l: 2, cs: true, f: ["Maljut"],
    d: "«El Reino». Décima sefirá, en la base del Árbol: el mundo físico, donde todo se cumple. En la Cruz Cabalística corresponde a los pies." },
  { id: "columnas", t: "Las tres columnas", l: 3, f: ["tres columnas", "tres pilares", "columna de la Misericordia", "columna de la Severidad", "columna del Equilibrio", "columna central"],
    d: "Las sefirot se ordenan en tres columnas verticales: la de la Misericordia (derecha, activa), la de la Severidad (izquierda, receptiva) y la del Equilibrio (central), que reconcilia a las otras dos." },
  { id: "pilar-medio", t: "Pilar Medio", l: 2, cs: true, f: ["Pilar Medio"],
    d: "Ejercicio de la Golden Dawn en el que se visualizan, de la cabeza a los pies, las sefirot de la columna central sobre el propio cuerpo. Se practica en la lección 10." },
  { id: "triadas", t: "Tríadas", l: 3, f: ["tríada suprema", "tríada ética", "tríada astral", "tríadas"],
    d: "Los tres triángulos del Árbol: la tríada suprema (1, 2, 3), el mundo de las ideas puras; la ética (4, 5, 6), el corazón; y la astral (7, 8, 9), la imaginación. Maljut queda sola debajo." },
  { id: "abismo", t: "El Abismo", l: 3, cs: true, f: ["Abismo"],
    d: "En la Qabalah hermética, el hueco que separa las tres sefirot de arriba del resto del Árbol. En él está Daat. «Cruzar el Abismo» es pasar de saber a comprender de verdad." },
  { id: "atsilut", t: "Atsilut", l: 3, cs: true, f: ["Atsilut"],
    d: "«Emanación». El primero y más alto de los cuatro mundos: la voluntad divina. Corresponde a la Yod de YHVH y al Fuego." },
  { id: "beria", t: "Beriá", l: 3, cs: true, f: ["Beriá"],
    d: "«Creación». El segundo de los cuatro mundos: el de las ideas. Corresponde a la primera He de YHVH y al Agua." },
  { id: "yetsira", t: "Yetsirá", l: 3, cs: true, f: ["Yetsirá"],
    d: "«Formación». El tercero de los cuatro mundos: el de las imágenes y las emociones. Corresponde a la Vav de YHVH y al Aire." },
  { id: "asia", t: "Asiá", l: 3, cs: true, f: ["Asiá"],
    d: "«Acción». El cuarto y más denso de los cuatro mundos: el mundo material. Corresponde a la He final de YHVH y a la Tierra." },
  { id: "tetragramaton", t: "Tetragrámaton (YHVH)", l: 3, cs: true, f: ["Tetragrámaton", "YHVH", "Yod He Vav He", "Yod, He, Vav, He"],
    d: "«Cuatro letras». El nombre más sagrado de Dios en la Biblia hebrea, יהוה. En el judaísmo no se pronuncia: se dice Adonai o HaShem. Por respeto, el curso lo deletrea: Yod, He, Vav, He." },
  { id: "adonai", t: "Adonai", l: 3, cs: true, f: ["Adonai"],
    d: "«Mi Señor». Lo que se dice en la oración judía en lugar del nombre YHVH. En el LBRP se pronuncia en el Sur, y es el nombre divino de Maljut." },
  { id: "hashem", t: "HaShem", l: 3, cs: true, f: ["HaShem"],
    d: "«El Nombre». Forma respetuosa de referirse a Dios en el judaísmo fuera de la oración." },
  { id: "eheieh", t: "Eheieh", l: 3, cs: true, f: ["Eheieh"],
    d: "«Yo soy» o «Yo seré», el nombre con que Dios se presenta a Moisés (Éxodo 3:14). Es el nombre divino de Kéter, y en el LBRP se pronuncia en el Oeste." },
  { id: "agla", t: "AGLA", l: 3, cs: true, f: ["AGLA"],
    d: "Palabra formada con las iniciales de Atá guibor le-olam Adonai, «Tú eres poderoso por siempre, Señor», de la oración judía diaria. En el LBRP se pronuncia en el Norte." },
  { id: "amida", t: "Amidá", l: 3, cs: true, f: ["Amidá"],
    d: "«De pie». La oración central del rezo judío diario, que se recita de pie." },
  { id: "escalas", t: "Escalas de color", l: 3, f: ["escala de la Reina", "escalas del Rey", "escalas de color", "escala del Rey"],
    d: "Los cuatro juegos de colores que la Golden Dawn dio a cada sefirá, uno por mundo: Rey (Atsilut), Reina (Beriá), Príncipe (Yetsirá) y Princesa (Asiá). La de la Reina es la más usada para meditar." },
  { id: "adam-kadmon", t: "Adam Kadmón", l: 3,
    d: "«El Hombre primordial». En la Cábala, la primera forma humana del universo, un cuerpo cósmico del que el ser humano es reflejo." },
  { id: "pataj", t: "Pataj Eliyahu", l: 3,
    d: "«Elías empezó a hablar». Oración que abre los Tikunéi Zóhar y describe las sefirot como partes de un cuerpo. Muchas comunidades sefardíes la recitan antes del Shabat." },
  { id: "shabat", t: "Shabat", l: 3, cs: true, f: ["Shabat"],
    d: "El día de descanso judío, del atardecer del viernes al del sábado." },
  { id: "jasidismo", t: "Jasidismo", l: 3, f: ["jasidismo", "jasídico", "jasídicos"],
    d: "Movimiento místico judío nacido en el siglo XVIII en Europa oriental, que puso la Cábala al alcance de la gente común a través de la alegría y la oración. Jabad es una de sus ramas." },

  // ── Lección 3: geometría ──
  { id: "geometria-sagrada", t: "Geometría sagrada", l: 3,
    d: "La idea, que viene de Pitágoras y Platón, de que las formas geométricas básicas expresan el orden del universo. Bajo este nombre circula también mucho material moderno sin base." },
  { id: "monada", t: "Mónada", l: 3, f: ["mónada", "díada", "tétrada"],
    d: "Para los pitagóricos, la unidad, el principio de todos los números, representada por un punto. La díada es el dos y la tétrada, el cuatro." },
  { id: "tetractys", t: "Tetractys", l: 3,
    d: "Triángulo de diez puntos en filas de 1, 2, 3 y 4, sagrado para los pitagóricos: el punto, la línea, la superficie y el volumen. Diez puntos, como diez sefirot." },
  { id: "vesica", t: "Vesica piscis", l: 3,
    d: "«Vejiga de pez». La figura en forma de almendra que forman dos círculos iguales que pasan cada uno por el centro del otro. Es la primera construcción de los Elementos de Euclides." },
  { id: "mandorla", t: "Mandorla", l: 3, f: ["mandorla"],
    d: "«Almendra», en italiano. El marco en forma de vesica piscis que rodea a Cristo o a la Virgen en el arte medieval, como zona donde se tocan el cielo y la tierra." },
  { id: "pantocrator", t: "Pantocrátor", l: 3,
    d: "«Todopoderoso». Representación de Cristo en majestad, sentado y bendiciendo, típica del arte bizantino y románico." },
  { id: "flor-vida", t: "Flor de la Vida", l: 3,
    d: "Red de círculos iguales entrelazados que aparece como adorno en muchas culturas. El nombre y la idea de que contiene el Árbol son modernos, de la Nueva Era de los años noventa." },
  { id: "aurea", t: "Proporción áurea", l: 3, f: ["proporción áurea", "número de oro", "divina proporción"],
    d: "Número que vale aproximadamente 1,618 y se escribe φ (fi). Aparece de forma exacta en el pentágono y el pentagrama. Muchas afirmaciones sobre su presencia en edificios y en la naturaleza son exageradas." },
  { id: "pentagrama", t: "Pentagrama", l: 3, f: ["pentagrama", "pentagramas", "estrella de cinco puntas"],
    d: "Estrella de cinco puntas. En la Golden Dawn representa los cuatro elementos gobernados por el espíritu, y al ser humano, el microcosmos. Durante siglos fue un símbolo de protección y de salud." },
  { id: "hexagrama", t: "Hexagrama", l: 3, f: ["hexagrama", "estrella de seis puntas", "estrella de seis rayos", "Sello de Salomón"],
    d: "Estrella de seis puntas formada por dos triángulos entrelazados, el Fuego que sube y el Agua que baja: la unión de los opuestos y el macrocosmos. Como estrella de David, símbolo del pueblo judío, tiene otra historia (lección 8)." },
  { id: "solidos", t: "Sólidos platónicos", l: 3, f: ["sólidos platónicos", "cinco sólidos"],
    d: "Los únicos cinco cuerpos con todas sus caras iguales y regulares: tetraedro, octaedro, icosaedro, cubo y dodecaedro. Platón asoció los cuatro primeros a los elementos y el dodecaedro al universo." },
  { id: "quinta-esencia", t: "Quinta esencia", l: 3, f: ["quinta esencia", "quintaesencia", "éter"],
    d: "El quinto elemento, más sutil que el fuego, el aire, el agua y la tierra: el éter o espíritu. En el pentagrama es la punta superior." },

  // ── Lección 3: lado oscuro y Luria ──
  { id: "qliphoth", t: "Qliphoth (kelipot)", l: 3, f: ["Qliphoth", "kelipot", "kelipá"],
    d: "«Cáscaras». La parte exterior y muerta de la realidad, que oculta la luz. En la Qabalah hermética, fuerzas desequilibradas, reflejo invertido del Árbol. El mal, en la Cábala, es sobre todo desequilibrio." },
  { id: "tsimtsum", t: "Tsimtsum", l: 3, f: ["tsimtsum"],
    d: "«Contracción». En la Cábala de Isaac Luria, el gesto con que el Ein Sof se retira para dejar sitio al mundo." },
  { id: "vasos", t: "Rotura de los vasos", l: 3, f: ["rotura de los vasos", "shevirat ha-kelim"],
    d: "En la Cábala de Luria, los recipientes que debían contener la luz divina no la resisten y se rompen; chispas de luz quedan atrapadas en los pedazos, que son las cáscaras." },
  { id: "tikun", t: "Tikún", l: 3, f: ["tikún", "tikun"],
    d: "«Reparación». La tarea humana, según Luria, de liberar con buenas acciones las chispas de luz atrapadas y recomponer el mundo (tikún olam)." },

  // ── Lección 3: ritual ──
  { id: "lbrp", t: "LBRP", l: 3, cs: true, f: ["LBRP", "Ritual Menor de Destierro del Pentagrama"],
    d: "Ritual Menor de Destierro del Pentagrama (en inglés, Lesser Banishing Ritual of the Pentagram). Ritual de la Golden Dawn que limpia y protege el espacio trazando un pentagrama en cada punto cardinal." },
  { id: "desterrar", t: "Desterrar", l: 3, f: ["desterrar", "destierro", "destierran"],
    d: "En magia ceremonial, alejar de tu espacio y de tu mente las influencias que no quieres. Es lo contrario de invocar, que es atraerlas." },
  { id: "arcangel", t: "Arcángeles", l: 3, f: ["arcángeles", "arcángel"],
    d: "Los ángeles principales. En el LBRP se invocan cuatro, uno por punto cardinal: Rafael (Este, Aire), Miguel (Sur, Fuego), Gabriel (Oeste, Agua) y Uriel (Norte, Tierra)." },
  { id: "notarikon", t: "Notarikón", l: 3, f: ["notarikón"],
    d: "Técnica cabalística que forma una palabra con las iniciales de una frase, o lee cada letra de una palabra como inicial de otra. Se estudia en la lección 7." },
  { id: "gematria", t: "Gematría", l: 1, f: ["gematría"],
    d: "Técnica que suma el valor numérico de las letras de una palabra hebrea y relaciona entre sí las palabras que dan el mismo número. Se estudia en la lección 7." },
  { id: "reduccion", t: "Reducción", l: 1, f: ["reducción", "redúcelo"],
    d: "En numerología, sumar las cifras de un número hasta quedarse con una sola, o con un número maestro como el 11: 137 → 1 + 3 + 7 = 11." },
  { id: "chakras", t: "Chakras", l: 3, f: ["chakras", "chakra"],
    d: "«Ruedas». Centros de energía del cuerpo según el yoga y el tantra de la India. Su mezcla con el Árbol de la Vida es del siglo XX (lección 10)." },
  { id: "enraizarse", t: "Enraizarse", l: 3, f: ["Enráizate", "enraizarse", "enraizarte"],
    d: "Volver del todo al cuerpo y a la vida cotidiana después de una práctica: comer, caminar, tocar la tierra. Es el equilibrio de Maljut." },
  { id: "apofenia", t: "Apofenia", l: 3,
    d: "Tendencia a ver patrones, señales o relaciones con sentido en datos que en realidad son casuales. Se estudia en la lección 8." },

  // ── Lección 4: las 22 letras ──
  { id: "constructoras", t: "Letras constructoras", l: 4, f: ["constructoras"],
    d: "Así llama la tradición a las 22 letras hebreas, porque según el Séfer Yetsirá Dios formó el mundo grabándolas, pesándolas y combinándolas." },
  { id: "32-senderos", t: "Treinta y dos senderos de sabiduría", l: 4, f: ["treinta y dos senderos", "32 senderos"],
    d: "Con ellos, dice la primera frase del Séfer Yetsirá, se creó el mundo: los diez números (las sefirot) y las 22 letras. En el Árbol de la Golden Dawn las sefirot son los senderos 1 a 10 y las letras, del 11 al 32." },
  { id: "protosinaitica", t: "Escritura protosinaítica", l: 4, f: ["protosinaítica"],
    d: "La primera escritura alfabética conocida, de hacia el 1800 a. C., en Egipto y el Sinaí: dibujos tomados de los jeroglíficos que valen por el primer sonido de su nombre. De ella vienen casi todos los alfabetos." },
  { id: "paleohebreo", t: "Paleohebreo", l: 4, f: ["paleohebreo", "paleohebrea"],
    d: "La escritura hebrea antigua, muy parecida a la fenicia, que se usó hasta el destierro en Babilonia. Los samaritanos siguen usando una escritura derivada de ella." },
  { id: "cuadrada", t: "Escritura cuadrada", l: 4, f: ["escritura cuadrada", "ketav ashurí"],
    d: "La forma de las letras hebreas que se usa desde la Antigüedad hasta hoy, tomada del arameo tras el destierro en Babilonia. El Talmud la llama ketav ashurí, «escritura asiria»." },
  { id: "abyad", t: "Abyad", l: 4, f: ["abyad"],
    d: "Sistema de escritura que solo anota las consonantes, como el hebreo y el árabe. Las vocales las pone quien lee, o se añaden con signos aparte." },
  { id: "niqqud", t: "Niqqud", l: 4, f: ["niqqud"],
    d: "Los puntos y rayitas que se añaden a las letras hebreas para indicar las vocales. Lo fijaron los masoretas entre los siglos VII y X." },
  { id: "masoretas", t: "Masoretas", l: 4, f: ["masoretas"],
    d: "Sabios judíos, sobre todo de Tiberíades (Galilea), que entre los siglos VII y X fijaron el texto de la Biblia hebrea con sus vocales, acentos y notas." },
  { id: "dagesh", t: "Dagesh", l: 4, f: ["dagesh"],
    d: "Punto dentro de una letra hebrea. En las letras dobles marca el sonido duro: בּ b frente a ב v, כּ k frente a כ j, פּ p frente a פ f." },
  { id: "madres", t: "Letras madres", l: 4, f: ["letras madres", "letra madre", "tres madres"],
    d: "Alef, Mem y Shin (א מ ש). En el Séfer Yetsirá son el aire, el agua y el fuego, de los que nace todo lo demás." },
  { id: "dobles", t: "Letras dobles", l: 4, f: ["letras dobles", "letra doble", "siete dobles"],
    d: "Bet, Guímel, Dálet, Kaf, Pe, Resh y Tav (ב ג ד כ פ ר ת). Tenían dos sonidos, duro y suave. En el Séfer Yetsirá corresponden a los siete planetas, los siete días y siete parejas de opuestos." },
  { id: "simples", t: "Letras simples", l: 4, f: ["letras simples", "letra simple", "doce simples"],
    d: "Las doce letras con un solo sonido: He, Vav, Záyin, Jet, Tet, Yod, Lámed, Nun, Sámej, Áyin, Tsadi y Qof. Corresponden a los doce signos del zodiaco y a los doce meses." },
  { id: "kamnefats", t: "Kamnefats", l: 4, f: ["kamnefats"],
    d: "Palabra inventada para recordar las cinco letras que tienen forma final: כמנפץ, Kaf, Mem, Nun, Pe y Tsadi." },
  { id: "231-puertas", t: "Las 231 puertas", l: 4, f: ["231 puertas", "231 parejas"],
    d: "Las combinaciones de dos en dos de las 22 letras (22 × 21 / 2 = 231). Según el Séfer Yetsirá, por ellas sale toda la creación. Son la base de la combinación de letras de Abulafia." },
  { id: "cubo-espacio", t: "Cubo del espacio", l: 4, f: ["cubo del espacio", "Cube of Space"],
    d: "Las seis direcciones, el centro y las doce aristas en que el Séfer Yetsirá coloca las letras. Dibujarlo como un cubo con una letra en cada cara es una construcción moderna de Paul Foster Case." },
  { id: "gra", una: true, t: "Gaón de Vilna (Gra)", l: 4, f: ["Gaón de Vilna", "Gra"], cs: true,
    d: "Elías ben Salomón (1720-1797), gran sabio judío de Vilna (Lituania). Su versión del Séfer Yetsirá es la que siguen las ediciones modernas, como la de Aryeh Kaplan." },
  { id: "kaplan", una: true, t: "Aryeh Kaplan", l: 4, f: ["Aryeh Kaplan"],
    d: "Rabino y físico estadounidense (1934-1983). Tradujo y comentó el Séfer Yetsirá y escribió sobre la meditación en la Cábala judía." },
  { id: "case", una: true, t: "Paul Foster Case", l: 4, f: ["Paul Foster Case"],
    d: "Ocultista estadounidense (1884-1954), miembro de la Golden Dawn y fundador de la escuela Builders of the Adytum. Escribió mucho sobre las letras y el tarot." },
  { id: "orden-caldeo", t: "Orden caldeo", l: 4, f: ["orden caldeo"],
    d: "El orden de los siete planetas antiguos según su distancia aparente a la Tierra, de más lejos a más cerca: Saturno, Júpiter, Marte, el Sol, Venus, Mercurio y la Luna." },
  { id: "shema", t: "Shemá", l: 4, cs: true, f: ["Shemá"],
    d: "«Escucha». La oración central del judaísmo, que empieza: «Escucha, Israel: el Señor es nuestro Dios, el Señor es uno» (Deuteronomio 6:4). Se reza por la mañana y por la noche." },
  { id: "bereshit", t: "Bereshit", l: 4, cs: true, f: ["Bereshit"],
    d: "«En el principio». La primera palabra de la Biblia y el nombre hebreo del libro del Génesis. Empieza por la letra Bet." },
  { id: "rashi", una: true, t: "Rashi", l: 4, cs: true, f: ["Rashi"],
    d: "Salomón ben Isaac de Troyes (1040-1105), el comentarista más leído de la Biblia y el Talmud. Su comentario acompaña a la Torá en casi todas las ediciones judías." },
  { id: "targum", t: "Targum", l: 4, cs: true, f: ["Targum"],
    d: "Traducción antigua de la Biblia hebrea al arameo, la lengua que hablaban los judíos en la Antigüedad. La más usada para la Torá es la de Onkelos." },
  { id: "vibrar", t: "Vibrar un nombre", l: 4, f: ["vibrar un nombre", "Vibrar un nombre", "vibrarlos", "vibrar los nombres"],
    d: "Técnica de la Golden Dawn: pronunciar un nombre divino con una espiración larga, en tono grave, hasta sentirlo resonar en todo el cuerpo." },
  { id: "elohim", t: "Elohim", l: 4, cs: true, f: ["Elohim"],
    d: "«Dios». Uno de los nombres divinos de la Biblia, el del primer versículo del Génesis. En el Árbol es el nombre de Biná." },
  { id: "abulafia", una: true, t: "Abraham Abulafia", l: 4, f: ["Abraham Abulafia", "Abulafia"],
    d: "Cabalista nacido en Zaragoza en 1240. Fundó la Cábala profética, que busca la experiencia directa de lo divino mediante la combinación de letras, la respiración y la concentración." },
  { id: "cabala-profetica", t: "Cábala profética", l: 4, f: ["Cábala profética"],
    d: "También llamada extática. La corriente de Abulafia: en vez de estudiar las sefirot, busca una experiencia interior directa por medio de las letras y los nombres divinos." },
  { id: "tseruf", t: "Combinación de letras (tseruf)", l: 4, f: ["combinación de letras", "tseruf"],
    d: "Práctica de combinar y pronunciar letras hebreas, sobre todo las de los nombres divinos, con las vocales y la respiración. Abulafia la llamó «la ciencia de la combinación» (jojmat ha-tseruf)." },
  { id: "atbash", t: "Atbash", l: 4, f: ["Atbash"],
    d: "Código que cambia cada letra hebrea por su simétrica: Alef por Tav, Bet por Shin, etc. Aparece ya en el libro de Jeremías. Se estudia en la lección 7." },
  { id: "van-helmont", una: true, t: "Van Helmont", l: 4, f: ["Van Helmont", "van Helmont"], cs: true,
    d: "Franciscus Mercurius van Helmont (1614-1698), alquimista flamenco, colaborador de la Kabbala denudata. Creyó que la forma de las letras hebreas dibuja la boca que las pronuncia." },
  // ── Lección 2: la Trinidad, la luz y el campo (añadido) ──
  { id: "mesmer", una: true, t: "Magnetismo animal", l: 2, f: ["magnetismo animal", "Mesmer"],
    d: "Fluido invisible que, según el médico Franz Anton Mesmer (1779), recorre los cuerpos y puede curar. La ciencia lo descartó, pero inspiró al esoterismo posterior: la «luz astral» de Lévi y las lecturas eléctricas de lo sagrado." },
  { id: "bonacci", una: true, t: "Santos Bonacci", l: 2, cs: true, f: ["Santos Bonacci", "Bonacci"],
    d: "Divulgador australiano de astroteología y sincretismo. Interpreta las religiones como un mismo mensaje sobre el Sol y sobre el campo eléctrico y magnético. El curso usa su lectura como doctrina simbólica, marcada como [Bonacci]." },
  { id: "sincretismo", t: "Sincretismo", l: 2, f: ["sincretismo", "sincrético", "sincrética"],
    d: "Unión de ideas de tradiciones distintas buscando lo que tienen en común. La palabra viene del griego: Plutarco cuenta que los cretenses, siempre peleados, se unían frente a un enemigo común." },
  { id: "dionisio", una: true, t: "Dionisio Areopagita", l: 2, f: ["Dionisio Areopagita", "Dionisio"], cs: true,
    d: "Místico cristiano de hacia el año 500, probablemente sirio, que escribió bajo el nombre de un discípulo de san Pablo. Enseñó que Dios está más allá de todo lo que se puede decir: una «tiniebla más que luminosa»." },
  { id: "botsina", t: "Lámpara de oscuridad", l: 2, f: ["lámpara de oscuridad", "botsiná de-kardinuta"],
    d: "En arameo, botsiná de-kardinuta. Según el Zóhar, lo primero que salió del Ein Sof: una llama oscura, sin color, de la que nacieron todos los colores y medidas." },
  { id: "toroide", t: "Toroide", l: 2, f: ["toroide"],
    d: "Forma de rosquilla. Es la forma del campo de un imán, con líneas que salen de un polo y vuelven por el otro. Bonacci la usa como imagen de todo el universo." },
  { id: "antielectricidad", t: "Antielectricidad", l: 2, f: ["antielectricidad"],
    d: "En el sistema de Bonacci, el centro en reposo, sin polos, del que salen el magnetismo y la electricidad. Él lo llama también dieléctrico y lo identifica con el Padre. No es un término de la física." },
  { id: "trinidad", t: "Trinidad", l: 2, f: ["Trinidad", "Santísima Trinidad", "trinidades"],
    d: "Doctrina cristiana de un solo Dios en tres personas iguales: Padre, Hijo y Espíritu Santo. La fijaron los concilios de Nicea (325) y Constantinopla (381)." },
  { id: "homoousios", t: "Homooúsios", l: 2, f: ["homooúsios"],
    d: "«De la misma sustancia». Palabra griega del Credo de Nicea: el Hijo es de la misma sustancia que el Padre, no inferior a él." },
  { id: "tertuliano", una: true, t: "Tertuliano", l: 2, cs: true, f: ["Tertuliano"],
    d: "Escritor cristiano de Cartago (h. 160-220). Fue el primero en usar en latín la palabra Trinitas, y la explicó con el Sol, el rayo y el punto de luz." },
  { id: "hildegarda", una: true, t: "Hildegarda de Bingen", l: 2, f: ["Hildegarda de Bingen", "Hildegarda"], cs: true,
    d: "Abadesa alemana (1098-1179), mística, compositora y naturalista. En el Scivias describió e hizo pintar sus visiones, entre ellas la Trinidad como luz, figura azul y fuego." },
  { id: "ondas", t: "Onda longitudinal y transversal", l: 2, f: ["onda longitudinal", "onda transversal", "ondas longitudinales", "ondas transversales"],
    d: "Una onda longitudinal se comprime y se expande en la dirección en que avanza, como el sonido. Una transversal sube y baja de lado, como la luz o una cuerda. Bonacci las usa como imágenes del magnetismo y de la electricidad." },
  { id: "trimurti", t: "Trimurti", l: 2, f: ["Trimurti"],
    d: "«Tres formas». En el hinduismo, Brahma que crea, Vishnu que conserva y Shiva que disuelve, vistos como tres funciones de lo divino." },
  { id: "sat-chit-ananda", t: "Sat-chit-ānanda", l: 2, f: ["sat-chit-ānanda", "Sat-chit-ānanda"],
    d: "«Ser, conciencia y gozo». En el Vedanta, los tres aspectos con que se describe el Absoluto, Brahman." },
  { id: "shakti", t: "Śakti", l: 2, f: ["śakti", "Śakti"],
    d: "En el hinduismo, la energía o potencia femenina de un dios, inseparable de él. Radha es la śakti de Krishna." },
  { id: "arrio", una: true, t: "Arrio", l: 2, cs: true, f: ["Arrio"],
    d: "Sacerdote de Alejandría (h. 256-336) que enseñó que el Hijo es inferior al Padre. El concilio de Nicea condenó su tesis en el año 325." },
  { id: "poimandres", t: "Poimandres", l: 2, f: ["Poimandres"],
    d: "Primer tratado del Corpus Hermeticum (siglos II-III). Cuenta la creación y el viaje del alma, que al subir devuelve a cada esfera planetaria el vicio que recibió de ella." },
  // ── Lección 3: añadidos ──
  { id: "abba-imma", t: "Abba e Imma", l: 3, cs: true, f: ["Abba", "Imma"],
    d: "«Padre» y «Madre» en arameo: los nombres que el Zóhar da a Jojmá y a Biná, de cuya unión nace el Hijo, Zeir Anpín." },
  { id: "zeir-anpin", t: "Zeir Anpín", l: 3, f: ["Zeir Anpín"],
    d: "«El Rostro Menor» o «el Impaciente». En el Zóhar, el Hijo: las seis sefirot de Jésed a Yesod, con Tiféret en el centro. Su pareja es Maljut, la Novia." },
  { id: "angulo-aureo", t: "Ángulo áureo", l: 3, f: ["ángulo áureo"],
    d: "Unos 137,5°: la parte de la vuelta completa que corresponde a la proporción áurea. Muchas plantas colocan así sus hojas y semillas." },
  { id: "fibonacci", t: "Serie de Fibonacci", l: 3, f: ["serie de Fibonacci", "Fibonacci"],
    d: "1, 1, 2, 3, 5, 8, 13, 21…: cada número es la suma de los dos anteriores. El cociente entre dos seguidos se acerca a la proporción áurea." },
  // ── Lección 4: añadidos ──
  { id: "estrella-magica", t: "Estrella mágica", l: 4, f: ["estrella mágica"],
    d: "Estrella de seis puntas con los números del 1 al 12 en sus cruces, de modo que cada línea suma 26. La suma es obligada por aritmética: 78 × 2 ÷ 6 = 26." },
  { id: "lunacion", t: "Lunación", l: 4, f: ["lunación", "lunaciones"],
    d: "El tiempo de una luna nueva a la siguiente: unos 29,5 días. Un año tiene unas 12,4." },

  // ── Egipto: dioses, lugares y términos ──
  { id: "osiris", t: "Osiris", l: 2,
    d: "Dios egipcio de los muertos, la resurrección y la fertilidad. Según el mito, su hermano Seth lo mató y lo despedazó; su esposa Isis reunió los pedazos y lo devolvió a la vida, y desde entonces reina en el más allá y juzga a los difuntos. Se le pinta envuelto como una momia, con piel verde o negra, el cayado y el látigo." },
  { id: "isis", t: "Isis", l: 2,
    d: "Diosa egipcia, esposa y hermana de Osiris y madre de Horus. Gran maga, recompuso el cuerpo de Osiris. Su culto se extendió por todo el Imperio romano, y su imagen amamantando a Horus es un antecedente probable de la Virgen con el Niño." },
  { id: "horus", t: "Horus", l: 2, f: ["Horus"],
    d: "Dios egipcio con cabeza de halcón, hijo de Osiris e Isis. Venció a Seth y heredó el trono de su padre: cada faraón vivo era considerado un Horus. Sus dos ojos son el Sol y la Luna." },
  { id: "ojo-horus", t: "Ojo de Horus", l: 2, f: ["ojo de Horus", "ojos de Horus", "udjat"],
    d: "El ojo que Seth arrancó a Horus y que Thot curó. Llamado udjat, «el sano», fue el amuleto de protección más usado en Egipto." },
  { id: "neftis", t: "Neftis", l: 2, cs: true, f: ["Neftis"],
    d: "Diosa egipcia, hermana de Isis, Osiris y Seth, y esposa de este. Llora a Osiris junto a Isis y protege a los difuntos." },
  { id: "seth", t: "Seth", l: 2, cs: true, f: ["Seth"],
    d: "Dios egipcio del desierto, las tormentas y el desorden. Mató a su hermano Osiris y luchó contra Horus por el trono. No es simplemente el mal: también defiende la barca de Ra contra Apofis." },
  { id: "ra", t: "Ra", l: 2, cs: true, f: ["Ra", "Amón-Ra"],
    d: "Dios egipcio del sol. Cruza el cielo en su barca durante el día y el mundo subterráneo durante la noche, y renace cada mañana. Su gran centro de culto fue Heliópolis. Unido a Amón formó Amón-Ra, el rey de los dioses." },
  { id: "amon", t: "Amón", l: 2, cs: true, f: ["Amón"],
    d: "«El oculto». Dios de Tebas que llegó a ser el más importante de Egipto en el Imperio Nuevo (desde el 1550 a. C.), unido a Ra como Amón-Ra. Un himno lo describe como el nombre oculto de un dios cuyo rostro es Ra y cuyo cuerpo es Ptah." },
  { id: "ptah", t: "Ptah", l: 2, cs: true, f: ["Ptah"],
    d: "Dios creador de Menfis y patrón de los artesanos. Según un texto de su templo, creó el mundo con el pensamiento del corazón y la palabra de la lengua. Se le representa como una momia con un gorro ajustado." },
  { id: "anubis", t: "Anubis", l: 2, cs: true, f: ["Anubis"],
    d: "Dios egipcio con cabeza de chacal, protector de las tumbas y de la momificación. Guía al difunto y, en el juicio, pesa su corazón contra la pluma de Maat." },
  { id: "maat", t: "Maat", l: 2, cs: true, f: ["Maat"],
    d: "Diosa egipcia y a la vez idea: la verdad, la justicia y el orden del universo. Lleva una pluma en la cabeza. En el juicio de los muertos, el corazón del difunto se pesa contra esa pluma." },
  { id: "sokar", t: "Sokar", l: 2, cs: true, f: ["Sokar"],
    d: "Dios halcón de las tumbas de Menfis. Se fundió con Ptah y Osiris en un solo dios funerario, Ptah-Sokar-Osiris." },
  { id: "aton", t: "Atón y Akenatón", l: 2, cs: true, f: ["Atón", "Akenatón"],
    d: "Atón es el disco del sol. El faraón Akenatón (hacia 1353-1336 a. C.) lo convirtió en el único dios de Egipto, en el primer intento de monoteísmo conocido. A su muerte se volvió a los dioses tradicionales." },
  { id: "apofis", t: "Apofis", l: 2, cs: true, f: ["Apofis", "Apep"],
    d: "Serpiente gigante del caos que cada noche intenta detener la barca del sol en el mundo subterráneo, y cada noche es vencida." },
  { id: "nun-egipcio", t: "Nun (Egipto)", l: 2, f: [],
    d: "En Egipto, el océano oscuro e infinito que existía antes de la creación y del que surgió la primera colina de tierra. No hay que confundirlo con la Nun, la letra hebrea." },
  { id: "eneada", t: "Enéada", l: 2, f: ["Enéada", "Ennéada"],
    d: "Los nueve dioses de Heliópolis: Atum, el creador; Shu y Tefnut, el aire y la humedad; Geb y Nut, la tierra y el cielo; y sus hijos Osiris, Isis, Seth y Neftis." },
  { id: "kemet", t: "Kemet", l: 2, cs: true, f: ["Kemet"],
    d: "«La tierra negra». El nombre que los egipcios daban a su país, por el limo negro y fértil que deja el Nilo. El desierto era la «tierra roja»." },
  { id: "libro-muertos", t: "Libro de los Muertos", l: 2, f: ["Libro de los Muertos"],
    d: "Colección de fórmulas mágicas para guiar al difunto en el más allá; su nombre egipcio es «Libro de salir al día». Se copiaba en papiros que se enterraban con el muerto desde hacia el 1550 a. C. Su capítulo 125 describe el juicio ante Osiris." },
  { id: "anj", t: "Anj (ankh)", l: 2, f: ["anj", "ankh", "cruz ansada"],
    d: "Cruz con un asa en lo alto: el signo jeroglífico de la vida. Los dioses lo acercan a la nariz del faraón para darle el aliento vital." },
  { id: "jeroglificos", t: "Jeroglíficos", l: 2, f: ["jeroglíficos", "jeroglífico", "jeroglífica"],
    d: "«Grabados sagrados». La escritura del antiguo Egipto, con signos que valen por sonidos o por ideas. Se dejó de entender hacia el siglo V y la descifró Champollion en 1822." },
  { id: "faraon", t: "Faraón", l: 2, f: ["faraón", "faraones"],
    d: "El rey de Egipto, considerado hijo de Ra y encarnación de Horus. La palabra significa «casa grande», el palacio." },
  { id: "heliopolis", t: "Heliópolis", l: 2, cs: true, f: ["Heliópolis"],
    d: "«Ciudad del Sol» en griego. Ciudad sagrada junto al actual El Cairo, centro del culto a Ra y de la Enéada." },
  { id: "menfis", t: "Menfis", l: 2, cs: true, f: ["Menfis"],
    d: "Primera capital del Egipto unificado, cerca del actual El Cairo, y ciudad del dios Ptah." },
  { id: "tebas", t: "Tebas", l: 2, cs: true, f: ["Tebas"],
    d: "Ciudad del sur de Egipto, la actual Luxor, capital religiosa del Imperio Nuevo y ciudad de Amón. Allí están los templos de Karnak y Luxor y el Valle de los Reyes." },
  { id: "deir", t: "Deir el-Medina", l: 2,
    d: "Aldea de Tebas donde vivían los artesanos que excavaban y pintaban las tumbas reales. Ellos mismos se hicieron tumbas muy bien decoradas, como la de Sennedjem." },
  { id: "abidos", t: "Abidos", l: 3, cs: true, f: ["Abidos"],
    d: "Ciudad santa de Osiris, donde se creía enterrada su cabeza y a donde peregrinaban los egipcios. Tiene el gran templo del faraón Seti I." },
  { id: "hunefer", t: "Hunefer", l: 2, cs: true, f: ["Hunefer"],
    d: "Escriba real del faraón Seti I (hacia 1300 a. C.). Su Libro de los Muertos, hoy en el Museo Británico, tiene una de las mejores escenas del juicio ante Osiris." },
  { id: "sennedjem", t: "Sennedjem", l: 2, cs: true, f: ["Sennedjem"],
    d: "Artesano de Deir el-Medina en tiempos de Seti I y Ramsés II. Su tumba (TT1) conserva pinturas de colores muy vivos con Osiris y el más allá." },
];
